import numpy as np
from scipy.optimize import least_squares
d=np.load('train.npy')
resp,s,C,D=d
g=resp/D
# cascade n identical activation stages: g = s*E*(a*C)**n/((s+a*C)**n)
def f_erlang(X, a, E, n):
    s,C=X
    return s*E*(a*C)**n/((s+a*C)**n)
def resid(p): return (f_erlang((s,C),*p)-g)/g
best=None
for n in [1,2,3,4,5,6]:
    for a in [0.5,1,2,3,5]:
        for E in [0.5,1,2]:
            p0=[a,E,float(n)]
            try:
                r=least_squares(resid,p0,max_nfev=100000,bounds=([0,0,0.5],[50,50,20]))
                pred=f_erlang((s,C),*r.x)
                me=np.max(np.abs((pred-g)/g)); rm=np.sqrt(np.mean(((pred-g)/g)**2))
                if best is None or rm<best[0]: best=(rm,me,r.x)
            except: pass
print('best erlang gap',best)
